import ctypes

def inverse_cdf_tdist(P, nu):
    # Load required GSL libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define function signature
    gsl.gsl_cdf_tdist_Pinv.argtypes = [ctypes.c_double, ctypes.c_double]
    gsl.gsl_cdf_tdist_Pinv.restype = ctypes.c_double

    # Handle edge cases
    if P <= 0:
        return -ctypes.c_double(-1).value
    elif P >= 1:
        return ctypes.c_double(1).value
    elif nu == 1:
        # For nu=1, it's the standard Cauchy distribution
        return gsl.gsl_cdf_cauchy_Pinv(P)
    elif nu == 2:
        # For nu=2, it's the standard normal distribution
        return gsl.gsl_cdf_normal_Pinv(P)

    # Call the GSL function
    return gsl.gsl_cdf_tdist_Pinv(P, nu)

