class gsl_function(ctypes.Structure):
    _fields_ = [('function', ctypes.POINTER(ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double))),
                ('params', ctypes.POINTER(ctypes.c_double))]

class gsl_integration_qaws_table(ctypes.Structure):
    pass

class gsl_integration_workspace(ctypes.Structure):
    pass

def create_workspace(limit):
    return gsl.gsl_integration_workspace_create_qaws(limit)

def create_qaws_table():
    return gsl.gsl_integration_qaws_table_create()

def free_workspace(workspace):
    gsl.gsl_integration_workspace_free(workspace)

def free_qaws_table(table):
    gsl.gsl_integration_qaws_table_free(table)

def my_function(x):
    return np.sin(x)

def compute_integral(f, a, b, table, epsabs, epsrel, limit, workspace):
    f_c = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(my_function)
    func = gsl_function(f_c, ctypes.pointer(ctypes.c_double()))
    gsl.gsl_integration_qaws(&func, ctypes.c_double(a), ctypes.c_double(b), table, ctypes.c_double(epsabs), ctypes.c_double(epsrel), ctypes.c_int(limit), workspace)
    result = ctypes.c_double()
    error = ctypes.c_double()
    gsl.gsl_integration_qaws_result(workspace, &result, &error)
    return result.value, error.value

