import ctypes

class gsl_combination(ctypes.Structure):
    _fields_ = []

class TestCombination:
    def __init__(self):
        self.comb = gsl_combination()

def gsl_combination_fprintf_py(file_obj, comb, format_str):
    c_file = ctypes.c_void_p(file_obj.fileno())
    c_comb = ctypes.pointer(comb)
    c_format_str = ctypes.c_char_p(format_str.encode('utf-8'))
    result = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so").gsl_combination_fprintf(c_file, c_comb, c_format_str)
    if result != 0:
        raise RuntimeError("GSL function failed with error code: {}".format(result))
    return 0

def write_combination_to_file(file_obj, comb, format_str):
    if not isinstance(file_obj, file):
        raise TypeError("file_obj must be a file object")
    if not isinstance(comb, gsl_combination):
        raise TypeError("comb must be a gsl_combination object")
    if not isinstance(format_str, str):
        raise TypeError("format_str must be a string")
    try:
        gsl_combination_fprintf_py(file_obj, comb, format_str)
        return 0
    except Exception as e:
        raise RuntimeError("Failed to write combination to file: {}".format(e))

