import ctypes
import numpy as np

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def f1(self, x):
        return self.func(x)

    def f2(self, x):
        return self.func(x)

    def f3(self, x):
        return self.func(x)

def integrate(function, a, b):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define function pointers
    gsl.gsl_integration_qk21_f1.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_integration_qk21_f1.restype = None

    # Create GSLFunction instance
    gsl_func = GSLFunction(function)

    # Prepare output variables
    result = ctypes.c_double(0.0)
    abs_error = ctypes.c_double(0.0)
    resabs = ctypes.c_double(0.0)
    resasc = ctypes.c_double(0.0)

    # Call the GSL function
    gsl.gsl_integration_qk21_f1(
        ctypes.byref(gsl_func.f1),
        ctypes.c_double(a),
        ctypes.c_double(b),
        ctypes.byref(result),
        ctypes.byref(abs_error),
        ctypes.byref(resabs),
        ctypes.byref(resasc)
    )

    return float(result.value), float(abs_error.value), float(resabs.value), float(resasc.value)

# Example usage
