def integrate_function(f, pts, epsabs, epsrel, limit):
    # Convert Python function to C function
    f_c = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(f)

    # Convert points array to C array
    pts_c = (ctypes.c_double * len(pts))()
    for i in range(len(pts)):
        pts_c[i] = pts[i]

