    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    compute_bessel_jl = _lib.compute_bessel_jl
    compute_bessel_jl.argtypes = [ctypes.c_int, ctypes.c_double]
    compute_bessel_jl.restype = ctypes.c_double


def compute_bessel_jl(l, x):
    return GSLResult.compute_bessel_jl(l, x)

